import Foundation

/// What may enter the clipboard history.
public enum ClipboardPolicy {
    /// Marks what the app itself put on the pasteboard (pasting an old item), so it is not recorded as new.
    public static let ownMarker = "\(AppIdentity.bundleID).clip"

    /// Pasteboard types by which an app says "do not keep this" (the nspasteboard.org convention
    /// password managers follow).
    public static let privateTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    /// Apps never recorded unless the user removes them from the list.
    /// Marks a copy that arrived from another device through Universal Clipboard (an iPhone's
    /// Passwords app among them). Such copies are not kept: what was copied there stays there.
    public static let remoteClipboardType = "com.apple.is-remote-clipboard"

    public static let defaultIgnoredApps: [String] = [
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.apple.Passwords",
        "com.apple.keychainaccess",
        "com.bitwarden.desktop",
        "com.dashlane.dashlanephonefinal",
        "com.lastpass.LastPass",
        "org.keepassxc.keepassxc",
    ]

    /// `types` are the pasteboard's type identifiers; `sourceBundleID` is the app in front when the copy happened.
    public static func shouldRecord(types: [String], sourceBundleID: String?, ignoredApps: Set<String>, paused: Bool) -> Bool {
        if paused { return false }
        if types.contains(ownMarker) { return false }
        if !privateTypes.isDisjoint(with: types) { return false }
        if types.contains(remoteClipboardType) { return false }
        if let sourceBundleID, ignoredApps.contains(sourceBundleID) { return false }
        return true
    }

    /// A copy that is nothing but one web address is a link; anything else is text.
    public static func kind(forText text: String) -> ClipKind {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.contains(where: \.isWhitespace),
              let components = URLComponents(string: trimmed),
              let scheme = components.scheme?.lowercased(), scheme == "http" || scheme == "https",
              let host = components.host, !host.isEmpty else { return .text }
        return .link
    }
}
